package za.ac.cput.repository; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import za.ac.cput.domain.Payment; import static org.junit.jupiter.api.Assertions.*; @SpringBootTest class PaymentRepositoryImplTest{@Autowired PaymentRepository repository; @Test void saveReadDelete(){Payment x=za.ac.cput.factory.PaymentFactory.createPayment("P001","B1",100,java.time.LocalDate.now(),"Card","Paid"); repository.save(x); assertTrue(repository.findById("P001").isPresent()); repository.deleteById("P001"); assertTrue(repository.findById("P001").isEmpty());}}